[CmdletBinding()]
param(
    [switch]$SkipModelDownload,
    [switch]$NoAutostart,
    [switch]$NoLaunch,
    [string]$RecordingHotkey = "f24"
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$stage = Join-Path $env:TEMP ("WhisperSeamlessInstaller-" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Force -Path $stage | Out-Null

function Write-EmbeddedFile([string]$RelativePath, [string]$Base64) {
    $target = Join-Path $stage $RelativePath
    $parent = Split-Path -Parent $target
    if ($parent) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }
    [IO.File]::WriteAllBytes($target, [Convert]::FromBase64String($Base64))
}

try {
    $b64 = ""
    $b64 += ""
    $b64 += ""
    Write-EmbeddedFile "Install-WhisperSeamless.ps1" $b64
    $b64 = ""
    $b64 += ""
    Write-EmbeddedFile "Uninstall-WhisperSeamless.ps1" $b64
    $b64 = ""
    $b64 += ""
    Write-EmbeddedFile "VERSION.json" $b64
    $b64 = ""
    $b64 += ""
    $b64 += ""
    $b64 += ""
    Write-EmbeddedFile "patches/apply_seamless_patch.py" $b64
    $b64 = ""
    $b64 += ""
    Write-EmbeddedFile "config/configure.py" $b64
    $b64 = ""
    $b64 += ""
    Write-EmbeddedFile "launcher/Launch-Whisper.vbs" $b64
    $b64 = ""
    $b64 += ""
    Write-EmbeddedFile "scripts/preflight.py" $b64
    $b64 = ""
    $b64 += ""
    Write-EmbeddedFile "scripts/Doctor.ps1" $b64

    $childArgs = @(
        "-NoProfile", "-ExecutionPolicy", "Bypass",
        "-File", (Join-Path $stage "Install-WhisperSeamless.ps1"),
        "-RecordingHotkey", $RecordingHotkey
    )
    if ($SkipModelDownload) { $childArgs += "-SkipModelDownload" }
    if ($NoAutostart) { $childArgs += "-NoAutostart" }
    if ($NoLaunch) { $childArgs += "-NoLaunch" }

    & powershell.exe @childArgs
    if ($LASTEXITCODE -ne 0) {
        throw "Whisper Seamless installation failed with exit code $LASTEXITCODE."
    }
}
finally {
    Remove-Item $stage -Recurse -Force -ErrorAction SilentlyContinue
}
